<script lang="ts">
 import WakeSlider from './WakeSlider.svelte';import DiaryBook from './DiaryBook.svelte';
 import {companion,updateData,notify} from '../state.svelte';import {emotions,dateKey,type Emotion,type EmotionRecord} from '../domain';
 import {saveReflection,reviewEmotion,correctEmotion,recordLabels,reflectionSummary,reflectionDraft} from '../companionship';
 import {pruneBackups} from '../bridge.svelte';import {interfaceState} from '../interfaceState.svelte';import Trend from './Trend.svelte';import ConfirmDialog from './ConfirmDialog.svelte';
 let range=$state(7),mood=$state<Emotion>('relaxed'),also=$state<Emotion[]>([]),intensity=$state(5),note=$state(''),context=$state(''),need=$state(''),action=$state('');
 let diaryOpen=$state(false),focusRecordId=$state('');
 let selectedDay=$state(''),selectedContext=$state(''),limit=$state(30),reviewId=$state(''),reviewLevel=$state(5),reviewNote=$state(''),helpful=$state<'yes'|'unsure'|'no'>('unsure'),deleting=$state('');
 let records=$derived.by(()=>{const start=new Date(interfaceState.now);start.setHours(0,0,0,0);start.setDate(start.getDate()-(range-1));return companion.data.emotions.filter(e=>e.at>=start.getTime());});
 let summary=$derived(reflectionSummary(records));let visible=$derived(records.filter(e=>(!selectedDay||dateKey(e.at)===selectedDay)&&(!selectedContext||e.reflection?.context===selectedContext)));
 $effect(()=>{range;selectedDay='';selectedContext='';limit=30;});
 function run(fn:()=>void){try{fn();}catch(e){notify(String(e).replace(/^Error: /,''));}}
 function toggle(label:Emotion){if(also.includes(label))also=also.filter(x=>x!==label);else if(also.filter(x=>x!==mood).length<2)also=[...also.filter(x=>x!==mood),label];else notify('一次最多记录三种感受，包括主要心情。');}
 function talk(record:EmotionRecord){interfaceState.chatDraft=reflectionDraft(record);location.hash='/chat';}
 function save(event:SubmitEvent){event.preventDefault();run(()=>{let id='';updateData(data=>{id=saveReflection(data,mood,note,{labels:also.filter(x=>x!==mood),intensity:Number(intensity),context,need,action}).id;});const record=companion.data.emotions.find(x=>x.id===id)!;selectedDay=dateKey(record.at);focusRecordId=id;diaryOpen=true;note='';context='';need='';action='';also=[];notify('心情已收好，之后可以回来看看。');if((event.submitter as HTMLElement)?.dataset.talk==='true')talk(record);});}
 function startReview(record:EmotionRecord){reviewId=record.id;reviewLevel=record.reflection?.review?.intensity??record.reflection?.intensity??5;reviewNote=record.reflection?.review?.note||'';helpful=record.reflection?.review?.helpful||'unsure';}
 function saveReview(event:SubmitEvent){event.preventDefault();run(()=>{updateData(data=>reviewEmotion(data,reviewId,Number(reviewLevel),reviewNote,helpful));reviewId='';notify('回看已保存。感受怎样变化，都值得被记录。');});}
 function when(at:number){return new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
 async function erase(){try{await pruneBackups(()=>updateData(data=>data.emotions=data.emotions.filter(e=>e.id!==deleting)));deleting='';notify('情绪记录与回看已删除。');}catch(e){notify(String(e));}}
</script>
<div class="emotion-journey">
 <div class="journey-toolbar"><p>记下感受 <span aria-hidden="true">→</span> 看见情境 <span aria-hidden="true">→</span> 试一小步 <span aria-hidden="true">→</span> 回来看看</p><div class="xy-tabs" aria-label="情绪回看范围"><button class:chosen={range===7} aria-pressed={range===7} onclick={()=>range=7}>近 7 天</button><button class:chosen={range===30} aria-pressed={range===30} onclick={()=>range=30}>近 30 天</button></div></div>
 <div class="journey-overview"><div><strong>{summary.days}</strong><span>留下记录的日子</span></div><div><strong>{summary.total}</strong><span>心情记录</span></div><div><strong>{summary.reviewed}</strong><span>事后回看</span></div><div><strong>{summary.actions}</strong><span>完成的小行动</span></div></div>
 <div class="emotion-grid">
  <section class="xy-panel mood-form"><h2>记录一下此刻</h2><p class="section-description">可以只写一句，也可以慢慢补充。</p><form onsubmit={save}>
   <label for="mood-label">我的心情</label><select id="mood-label" bind:value={mood}>{#each Object.entries(emotions) as [value,label]}<option value={value}>{label}</option>{/each}</select>
   <div class="range-heading"><label for="mood-intensity">感受强度</label><output for="mood-intensity">{intensity} / 10</output></div><WakeSlider id="mood-intensity" bind:value={intensity} reduced={companion.data.preferences.reduceMotion}/><small>只表示此刻感受有多强，不是好坏评分。</small>
   <label for="mood-note">想说的话 <span>可选</span></label><textarea id="mood-note" bind:value={note} rows="3" maxlength="2000" placeholder="是什么，让你有这样的心情？"></textarea>
   <details class="reflection-details"><summary>补充情境、需要与小行动</summary><fieldset><legend>同时还有的感受 <small>主要心情以外最多选 2 种</small></legend><div class="emotion-chips">{#each Object.entries(emotions).filter(([value])=>value!==mood) as [value,label]}<button type="button" class:chosen={also.includes(value as Emotion)} aria-pressed={also.includes(value as Emotion)} onclick={()=>toggle(value as Emotion)}>{label}</button>{/each}</div></fieldset>
   <label for="mood-context">当时的情境</label><input id="mood-context" bind:value={context} maxlength="120" list="emotion-context-list" placeholder="例如：工作、人际、独处、休息"/><datalist id="emotion-context-list">{#each summary.contexts.slice(0,12) as item}<option value={item.name}></option>{/each}</datalist>
   <label for="mood-need">此刻需要什么</label><input id="mood-need" bind:value={need} maxlength="200" placeholder="例如：被听见、有人陪、留一点空间"/>
   <label for="mood-action">愿意尝试的一小步</label><input id="mood-action" bind:value={action} maxlength="200" placeholder="例如：给自己倒杯水，去窗边坐一会儿"/>
   </details><div class="xy-actions"><button class="xy-btn primary" type="submit">保存心情</button><button class="xy-btn" type="submit" data-talk="true">保存，和小屿梳理</button></div><small>梳理内容会先放进对话输入框，由你决定是否发送。</small>
  </form></section>
  <div class="emotion-map-column"><section class="emotion-history"><DiaryBook records={records.filter(r=>!selectedContext||r.reflection?.context===selectedContext)} bind:open={diaryOpen} bind:selected={selectedDay} focusId={focusRecordId} reduced={companion.data.preferences.reduceMotion}>{#snippet children(record)}<article class="emotion-record">
   <div class="record-heading"><div><time>{when(record.at)}</time><h3>{recordLabels(record).map(label=>emotions[label]).join(' · ')}{#if record.reflection}<small>强度 {record.reflection.intensity}/10</small>{/if}</h3></div><span class="record-origin">{record.origin==='manual'?'你主动记录':record.confirmed?'AI 观察 · 你已确认':'AI 观察 · 待你确认'}</span></div>
   <p>{record.note||'给自己的心情留了一个位置。'}</p>{#if record.reflection}<dl class="reflection-facts">{#if record.reflection.context}<div><dt>当时</dt><dd>{record.reflection.context}</dd></div>{/if}{#if record.reflection.need}<div><dt>需要</dt><dd>{record.reflection.need}</dd></div>{/if}</dl>
    {#if record.reflection.action}<label class="reflection-action"><input type="checkbox" checked={record.reflection.actionDone} onchange={()=>run(()=>updateData(data=>{const r=data.emotions.find(e=>e.id===record.id)?.reflection;if(r)r.actionDone=!r.actionDone;}))}/><span>我的小行动：{record.reflection.action}</span><small>{record.reflection.actionDone?'已尝试':'还可以慢慢来'}</small></label>{/if}
    {#if record.reflection.review}<div class="reflection-result"><strong>后来，回来看看</strong><span>感受强度 {record.reflection.intensity} → {record.reflection.review.intensity}</span><p>{record.reflection.review.note||'为自己的变化，留下一点空间。'}</p><small>这一步：{record.reflection.review.helpful==='yes'?'对我有帮助':record.reflection.review.helpful==='no'?'这次不太适合':'还不确定'} · {when(record.reflection.review.at)}</small></div>{/if}
   {:else}<p class="quiet-note">这条旧记录没有填写强度与情境，仍保留原内容。</p>{/if}
   <div class="record-actions"><label class="sr-only" for={'emotion-'+record.id}>更正这条情绪</label><select id={'emotion-'+record.id} value={record.label} onchange={event=>run(()=>updateData(data=>correctEmotion(data,record.id,event.currentTarget.value as Emotion)))}>{#each Object.entries(emotions) as [value,label]}<option value={value}>{label}</option>{/each}</select><button class="text-button" onclick={()=>talk(record)}>和小屿梳理</button>{#if record.reflection}<button class="text-button" onclick={()=>startReview(record)}>{record.reflection.review?'修改回看':'事后回看'}</button>{/if}<button class="text-button danger-text" onclick={()=>deleting=record.id}>删除</button></div>
   {#if reviewId===record.id}<form class="review-form" onsubmit={saveReview}><div class="range-heading"><label for={'review-intensity-'+record.id}>现在的感受强度</label><output>{reviewLevel} / 10</output></div><WakeSlider id={'review-intensity-'+record.id} bind:value={reviewLevel} reduced={companion.data.preferences.reduceMotion}/><label for="review-helpful">这一步对我</label><select id="review-helpful" bind:value={helpful}><option value="unsure">还不确定</option><option value="yes">有帮助</option><option value="no">这次不太适合</option></select><label for="review-note">回看想说的话</label><textarea id="review-note" rows="2" maxlength="1000" bind:value={reviewNote}></textarea><div class="xy-actions"><button class="xy-btn primary" type="submit">保存回看</button><button class="xy-btn" type="button" onclick={()=>reviewId=''}>取消</button></div></form>{/if}
  </article>{/snippet}</DiaryBook></section><section class="xy-panel emotion-trend"><h2>每天记录了什么心情</h2><Trend records={records} days={range} selected={selectedDay} onselect={day=>selectedDay=day}/></section>
   <section class="xy-panel emotion-patterns"><h2>从记录里，慢慢发现</h2>{#if summary.total}<p>近 {range} 天，你在 {summary.days} 个日子里留下 {summary.total} 次记录，回来回看了 {summary.reviewed} 次。</p><div class="pattern-tags">{#each summary.labels.slice(0,6) as item}<span>{item.name}<b>{item.count} 次</b></span>{/each}</div><small>感受出现次数；一条记录可包含多种感受。</small><h3>记录过的情境</h3>{#if summary.contexts.length}<div class="context-tags">{#each summary.contexts as item}<button type="button" aria-pressed={selectedContext===item.name} class:chosen={selectedContext===item.name} onclick={()=>{selectedContext=selectedContext===item.name?'':item.name;selectedDay='';diaryOpen=true;}}>{item.name} <small>{item.count} 次</small></button>{/each}</div><p class="quiet-note">这些情境曾和感受一起出现，是否有关联，由你来判断。</p>{:else}<p class="quiet-note">补充“当时的情境”后，这里会汇总你实际记录过的内容。</p>{/if}{:else}<p class="module-empty">不急着总结自己。先留下一次感受，再慢慢认识它。</p>{/if}</section>
  </div>
 </div>
 <p class="module-caption">记录与观察不等于诊断。AI 的理解需要你确认，也可以随时更正或删除。</p>
</div>
{#if deleting}<ConfirmDialog destructive title="删除这次心情与回看？" description="原记录、情境、小行动与回看都会删除，并清理本机历史备份。已导出的副本需要另行处理。" confirmText="确认删除" onconfirm={erase} onclose={()=>deleting=''}/>{/if}
